"""Gerador de catalog.ts — 300+ produtos VendaMais"""
import os, re

ROOT = r"C:\PROJETOS\EXPOSTACKER\vendamais"
OUT = os.path.join(ROOT, "src", "lib", "catalog.ts")

VM = "VendaMais"
VS = "VendaMais Selecao"
BV = "Boa Vida"
CL = "Casa Limpa"
PA = "PetAmigo"

pid = [0]
prefixes = {"hortifruti":"h","acougue":"a","padaria":"p","frios":"f","laticinios":"l","bebidas":"b","mercearia":"m","congelados":"c","limpeza":"cl","higiene":"hg","bebe":"bb","pet":"pt"}

products = []

def P(name, brand, cat, sub, img_id, price, unit, weight, unitPrice, stock=100, prev=None, tags=None, byWeight=False, pricePerKg=None, approxWeight=None):
    pid[0] += 1
    cat_prefix = prefixes.get(cat, "x")
    slug = name.lower()
    slug = re.sub(r'[^a-z0-9]+', '-', slug).strip('-')
    if weight and not byWeight:
        w = re.sub(r'[^a-z0-9]', '', weight.lower())[:8]
        if w and w not in slug and len(slug) < 40:
            slug = f"{slug}-{w}"
    p = {"id": f"{cat_prefix}{pid[0]:03d}", "slug": slug, "name": name, "brand": brand,
         "category": cat, "subcategory": sub, "img_id": img_id, "price": price,
         "unit": unit, "weight": weight, "unitPrice": unitPrice, "stock": stock,
         "tags": tags or [], "byWeight": byWeight}
    if prev: p["previousPrice"] = prev; p["promotion"] = "oferta"
    if byWeight and pricePerKg: p["pricePerKg"] = pricePerKg; p["approxWeight"] = approxWeight
    products.append(p)

